<script>
  import { onMount } from 'svelte';
  import { t } from './i18n.js';
  import MarkdownContent from './MarkdownContent.svelte';
  export let token = '';
  export let admin = false;
  $: canPublish = admin || !!memberId;
  let memberId = '';
  let types = [], items = [], selectedType = '', selected = null, articles = [];
  let loading = true, saving = false, error = '', notice = '';
  let itemPage = 1, itemsHaveMore = false, loadingMore = false;
  let view = 'browse';
  let form = { kind: '', name: '', brand: '', subtitle: '', data: {}, isPublic: true };
  let typeName = '', field = { type: '', group: '基本信息', key: '', label: '', dataType: 'text', unit: '', required: false, options: [], helpText: '' };
  let table = { type: '', key: '', title: '', columns: [] }, columnDraft = '';
  let article = { hardwareId: '', title: '', summary: '', body: '' }, articleFiles = [];
  const headers = () => token ? { Authorization: `Bearer ${token}` } : {};
  async function api(url, options = {}) { const r = await fetch(url, { ...options, headers: { ...headers(), ...options.headers }, cache: 'no-store' }); if (!r.ok) { const e = await r.json().catch(()=>({})); throw new Error(e.message || `请求失败（${r.status}）`); } return r.status === 204 ? null : r.json(); }
  async function load() { loading=true;error='';try { const [schema,list]=await Promise.all([api('/api/hardware/schema'),api('/api/hardware/items?page=1'+(admin?'&all=true':''))]);types=schema.items;items=list.items;itemPage=1;itemsHaveMore=list.hasMore;if(token){try{memberId=(await api('/api/hpahub/me/center')).profile?.id||'';}catch{memberId='';}}if(!selectedType&&types.length)selectedType=types[0].key; } catch(e){error=e.message;}finally{loading=false;} }
  $: activeType=types.find(x=>x.key===selectedType);
  $: visibleItems=items.filter(x=>x.kind===selectedType);
  async function loadMoreItems(){if(loadingMore||!itemsHaveMore)return;loadingMore=true;try{const result=await api('/api/hardware/items?page='+(itemPage+1)+(admin?'&all=true':''));items=[...items,...result.items];itemPage+=1;itemsHaveMore=result.hasMore;}catch(e){error=e.message;}finally{loadingMore=false;}}
  function fieldValue(f,value){return f.dataType==='number'?(value===''?'':Number(value)):value;}
  async function open(item) { selected=item;view='detail';error='';try{articles=(await api(`/api/hardware/items/${item.id}/articles`)).items;}catch(e){articles=[];error=e.message;} }
  function newHardware(){form={kind:selectedType,name:'',brand:'',subtitle:'',data:{},isPublic:true};selected=null;view='edit';}
  function editHardware(item){form={...item,data:{...item.data},isPublic:item.isPublic};selected=item;view='edit';}
  async function saveHardware(){saving=true;error='';try{const method=selected?'PATCH':'POST',url='/api/hardware/items'+(selected?'/'+selected.id:'');const saved=await api(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(form)});const i=items.findIndex(x=>x.id===saved.id);items=i<0?[saved,...items]:items.map(x=>x.id===saved.id?saved:x);selected=saved;view='detail';}catch(e){error=e.message;}finally{saving=false;}}
  function addType(){view='type';typeName='';}
  async function saveType(){const label=typeName.trim();if(!label)return;const key=label.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')||`type_${Date.now()}`;try{await api('/api/hardware/types',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key,label})});await load();selectedType=key;view='configure';}catch(e){error=e.message;}}
  async function saveField(){field.type=activeType?.id;if(!field.key)field.key=field.label.toLowerCase().replace(/[^a-z0-9]+/g,'_')||`field_${Date.now()}`;try{await api('/api/hardware/fields',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(field)});field={type:'',group:'基本信息',key:'',label:'',dataType:'text',unit:'',required:false,options:[],helpText:''};await load();}catch(e){error=e.message;}}
  async function saveTable(){table.type=activeType?.id;table.columns=columnDraft.split(',').map((label,i)=>({key:`col_${i+1}`,label:label.trim()})).filter(c=>c.label);if(!table.key)table.key=`table_${Date.now()}`;try{await api('/api/hardware/tables',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(table)});table={type:'',key:'',title:'',columns:[]};columnDraft='';await load();}catch(e){error=e.message;}}
  function addRow(t){form.data={...form.data,[t.key]:[...(form.data[t.key]||[]),Object.fromEntries(t.columns.map(c=>[c.key,'']))]};}
  function updateCell(tableKey,rowIndex,colKey,value){const rows=[...(form.data[tableKey]||[])];rows[rowIndex]={...rows[rowIndex],[colKey]:value};form.data={...form.data,[tableKey]:rows};}
  async function saveArticle(){if(!selected)return;const body=new FormData();body.set('hardwareId',selected.id);body.set('title',article.title);body.set('summary',article.summary);body.set('body',JSON.stringify({markdown:article.body}));body.set('published','true');articleFiles.forEach(f=>body.append('images',f));try{await api('/api/hardware/articles',{method:'POST',body});article={hardwareId:selected.id,title:'',summary:'',body:''};articleFiles=[];await open(selected);notice='文章已发布。';}catch(e){error=e.message;}}
  onMount(load);
</script>
<main class="hardware-page dashboard">
  <header class="page-head"><div><p class="eyebrow">HPA LAB</p><h1>{$t('硬件数据库')}</h1><p>按类别记录硬件参数、测试报告与专栏文章。</p></div>{#if canPublish}<button class="primary" on:click={newHardware}>{$t('添加硬件')}</button>{/if}</header>
  {#if error}<p class="message error" role="alert">{error}</p>{/if}{#if notice}<p class="message success" role="status">{notice}</p>{/if}
  {#if loading}<p>{$t('正在加载…')}</p>{:else}
  <nav class="types">{#each types as type}<button class:active={selectedType===type.key} on:click={()=>{selectedType=type.key;view='browse';selected=null;}}>{type.label}</button>{/each}{#if admin}<button class="add-type" on:click={addType}>＋ {$t('添加分类')}</button>{/if}</nav>
  {#if view==='type'}<section class="panel"><h2>{$t('添加硬件分类')}</h2><label>{$t('分类名称')}<input bind:value={typeName} placeholder="例如：显示器" /></label><div class="actions"><button class="primary" on:click={saveType}>{$t('保存')}</button><button on:click={()=>view='browse'}>{$t('取消')}</button></div></section>
  {:else if view==='configure'}<section class="panel"><h2>{activeType?.label} · {$t('填写项目配置')}</h2><div class="config-grid"><form on:submit|preventDefault={saveField}><h3>{$t('添加参数')}</h3><label>{$t('分组')}<input bind:value={field.group}/></label><label>{$t('项目名称')}<input bind:value={field.label} required/></label><label>{$t('字段类型')}<select bind:value={field.dataType}><option value="text">{$t('文字')}</option><option value="number">{$t('数字')}</option><option value="boolean">{$t('是/否')}</option><option value="date">{$t('日期')}</option><option value="select">{$t('单选')}</option><option value="multiselect">{$t('多选')}</option></select></label>{#if ['select','multiselect'].includes(field.dataType)}<label>{$t('选项')}<input bind:value={field.optionText} placeholder="逗号分隔" on:input={()=>field.options=field.optionText.split(',').map(x=>x.trim()).filter(Boolean)}/></label>{/if}<label>{$t('单位')}<input bind:value={field.unit} placeholder="GHz、mm、Hz"/></label><label class="check"><input type="checkbox" bind:checked={field.required}/>{$t('必填')}</label><button class="primary">{$t('添加项目')}</button></form><form on:submit|preventDefault={saveTable}><h3>{$t('添加测试表格')}</h3><label>{$t('表格名称')}<input bind:value={table.title} required/></label><label>{$t('列名')}<input bind:value={columnDraft} placeholder="测试项目, 得分, 单位, 备注" required/></label><button class="primary">{$t('添加测试表格')}</button></form></div><h3>{$t('当前参数')}</h3><div class="chips">{#each activeType?.fields||[] as f}<span>{f.group} · {f.label} ({f.dataType||'text'})</span>{/each}</div><h3>{$t('当前测试表格')}</h3><div class="chips">{#each activeType?.tables||[] as tableDef}<span>{tableDef.title} · {tableDef.columns.length} {$t('列')}</span>{/each}</div></section>
  {:else if view==='edit'}<section class="panel"><div class="panel-head"><h2>{selected?'编辑硬件':'添加硬件'}</h2><button on:click={()=>view=selected?'detail':'browse'}>{$t('返回')}</button></div><form on:submit|preventDefault={saveHardware}><div class="fields"><label>{$t('分类')}<select bind:value={form.kind}>{#each types as typeItem}<option value={typeItem.key}>{typeItem.label}</option>{/each}</select></label><label>{$t('名称')}<input bind:value={form.name} required/></label><label>{$t('品牌')}<input bind:value={form.brand}/></label><label>{$t('型号 / 副标题')}<input bind:value={form.subtitle}/></label></div>{#each (types.find(kind=>kind.key===form.kind)?.fields||[]).filter(f=>!['name','brand','model','category','note'].includes(f.key)) as f}<label>{f.label}{#if f.unit} ({f.unit}){/if}{#if f.required} *{/if}{#if f.dataType==='boolean'}<input type="checkbox" checked={!!form.data[f.key]} on:change={e=>form.data={...form.data,[f.key]:e.currentTarget.checked}}/>{:else if f.dataType==='select'}<select value={form.data[f.key]||''} on:change={e=>form.data={...form.data,[f.key]:e.currentTarget.value}}><option value="">—</option>{#each f.options||[] as op}<option>{op}</option>{/each}</select>{:else if f.dataType==='multiselect'}<select multiple value={form.data[f.key]||[]} on:change={e=>form.data={...form.data,[f.key]:Array.from(e.currentTarget.selectedOptions).map(o=>o.value)}}>{#each f.options||[] as op}<option>{op}</option>{/each}</select>{:else}<input type={f.dataType==='number'?'number':f.dataType==='date'?'date':'text'} value={form.data[f.key]||''} required={f.required} on:input={e=>form.data={...form.data,[f.key]:fieldValue(f,e.currentTarget.value)}}/>{/if}{#if f.helpText}<small>{f.helpText}</small>{/if}</label>{/each}{#each (types.find(kind=>kind.key===form.kind)?.tables||[]) as tableDef}<section class="report-table"><div class="panel-head"><h3>{tableDef.title}</h3><button type="button" on:click={()=>addRow(tableDef)}>{$t('添加一行')}</button></div>{#each form.data[tableDef.key]||[] as row, ri}<div class="row">{#each tableDef.columns as c}<label>{c.label}<input value={row[c.key]||''} on:input={e=>updateCell(tableDef.key,ri,c.key,e.currentTarget.value)}/></label>{/each}<button type="button" on:click={()=>form.data={...form.data,[tableDef.key]:form.data[tableDef.key].filter((_,i)=>i!==ri)}}>{$t('删除')}</button></div>{/each}</section>{/each}<label class="check"><input type="checkbox" bind:checked={form.isPublic}/>{$t('公开此硬件报告')}</label><div class="actions"><button class="primary" disabled={saving}>{$t('保存报告')}</button><button type="button" on:click={()=>view=selected?'detail':'browse'}>{$t('取消')}</button></div></form></section>
  {:else if view==='detail' && selected}<section class="panel"><div class="panel-head"><div><p class="eyebrow">{types.find(kind=>kind.key===selected.kind)?.label} · {selected.brand}</p><h2>{selected.name}</h2><p>{selected.subtitle}</p></div>{#if admin || selected.submittedBy===memberId}<button on:click={()=>editHardware(selected)}>{$t('编辑报告')}</button>{/if}</div><h3>{$t('测试报告')}</h3><dl class="report">{#each (types.find(kind=>kind.key===selected.kind)?.fields||[]) as f}{#if selected.data?.[f.key]!==undefined && selected.data[f.key]!==''}<div><dt>{f.label}</dt><dd>{Array.isArray(selected.data[f.key])?selected.data[f.key].join('、'):selected.data[f.key]} {f.unit}</dd></div>{/if}{/each}</dl>{#each (types.find(kind=>kind.key===selected.kind)?.tables||[]) as tableDef}{#if selected.data?.[tableDef.key]?.length}<h3>{tableDef.title}</h3><div class="table-scroll"><table><thead><tr>{#each tableDef.columns as c}<th>{c.label}</th>{/each}</tr></thead><tbody>{#each selected.data[tableDef.key] as row}<tr>{#each tableDef.columns as c}<td>{row[c.key]}</td>{/each}</tr>{/each}</tbody></table></div>{/if}{/each}<h3>{$t('专栏文章')}</h3>{#if canPublish}<details class="article-editor"><summary>{$t('撰写专栏文章')}</summary><form on:submit|preventDefault={saveArticle}><label>{$t('文章标题')}<input bind:value={article.title} required/></label><label>{$t('摘要')}<textarea bind:value={article.summary}/></label><label>{$t('正文')}<textarea rows="12" bind:value={article.body} placeholder="支持 Markdown"/></label><label>{$t('添加图片')}<input type="file" accept="image/*" multiple on:change={e=>articleFiles=Array.from(e.currentTarget.files)}/></label><label class="check"><input type="checkbox" checked disabled/> {$t('发布文章')}</label><button class="primary">{$t('发布文章')}</button></form></details>{/if}{#each articles as a}<article class="article"><p class="eyebrow">{$t('专栏文章')}</p><h3>{a.title}</h3><p>{a.summary}</p>{#if a.body?.markdown}<MarkdownContent text={a.body.markdown}/>{/if}{#each a.images||[] as image}<img class="article-image" src={`/api/hardware/articles/${a.id}/images/${encodeURIComponent(image)}`} alt=""/>{/each}</article>{/each}<button on:click={()=>view='browse'}>{$t('返回列表')}</button></section>
  {:else}<section class="catalog-head"><div><h2>{activeType?.label||'硬件'}</h2><p>{visibleItems.length} {$t('条记录')}</p></div><div>{#if admin}<button on:click={()=>view='configure'}>{$t('配置录入项目')}</button>{/if}{#if canPublish}<button class="primary" on:click={newHardware}>{$t('添加硬件')}</button>{/if}</div></section>{#if visibleItems.length}<div class="hardware-grid">{#each visibleItems as item}<button class="hardware-card" on:click={()=>open(item)}>{#if item.cover}<img src={item.cover} alt=""/>{:else}<div class="cover-placeholder">HPA / LAB</div>{/if}<span>{item.brand}</span><h3>{item.name}</h3><p>{item.subtitle}</p><small>{$t('查看测试报告')}</small></button>{/each}</div>{:else}<p class="empty">{$t('暂无硬件记录。')}</p>{/if}{#if itemsHaveMore}<button class="load-more" on:click={loadMoreItems} disabled={loadingMore}>{$t('加载更多')}</button>{/if}{/if}
  {/if}
</main>
<style>
.hardware-page{max-width:1100px}.page-head,.panel-head,.catalog-head{display:flex;justify-content:space-between;align-items:center;gap:18px}.page-head{margin-bottom:24px}.eyebrow{font-size:11px;letter-spacing:.14em;color:var(--accent-deep)}.types{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0 24px}.types button,.panel button,.catalog-head button{padding:8px 14px;border:1px solid var(--border-default);border-radius:8px;background:var(--surface);color:var(--ink-secondary);cursor:pointer}.types button.active{background:var(--accent-soft);color:var(--accent-deep);border-color:var(--accent)}button.primary{background:var(--accent);color:#062414;border:0}.panel{padding:22px;border:1px solid var(--border-subtle);border-radius:14px;background:var(--surface);margin:16px 0}.panel label,.config-grid label{display:grid;gap:6px;margin:10px 0;color:var(--ink-secondary)}.panel input,.panel textarea,.panel select{width:100%;padding:9px 11px;border:1px solid var(--border-default);border-radius:7px;background:var(--surface-elevated);color:var(--ink-primary);font:inherit}.panel .check{display:flex;align-items:center}.check input{width:auto}.config-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.config-grid form{padding:16px;border:1px solid var(--border-subtle);border-radius:10px}.chips{display:flex;flex-wrap:wrap;gap:8px}.chips span{padding:6px 10px;background:var(--surface-tint);border-radius:20px;font-size:12px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.actions{display:flex;gap:10px;margin-top:18px}.row{display:flex;align-items:end;gap:8px}.row label{flex:1}.report-table{margin:18px 0}.hardware-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px}.hardware-card{overflow:hidden;text-align:left;border:1px solid var(--border-subtle);border-radius:12px;background:var(--surface);color:var(--ink-primary);padding:0 0 16px;cursor:pointer}.hardware-card img,.cover-placeholder{display:grid;width:100%;height:150px;object-fit:cover;background:var(--surface-tint);place-items:center;color:var(--ink-subtle)}.hardware-card span,.hardware-card h3,.hardware-card p,.hardware-card small{display:block;margin:10px 14px}.hardware-card p{color:var(--ink-muted)}.report{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 20px}.report div{padding:10px 0;border-bottom:1px solid var(--border-subtle)}.report dt{color:var(--ink-muted);font-size:12px}.report dd{margin:4px 0;font-weight:600}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid var(--border-subtle)}.article{padding:18px 0;border-top:1px solid var(--border-subtle)}.article-image{max-width:100%;max-height:480px;display:block;margin:12px 0;border-radius:8px}.article-editor{margin:16px 0}.article-editor summary{cursor:pointer}.empty{padding:50px;text-align:center;color:var(--ink-muted)}@media(max-width:680px){.config-grid,.fields,.report{grid-template-columns:1fr}.page-head,.catalog-head{align-items:flex-start;flex-direction:column}.row{flex-wrap:wrap}}
</style>
